      + '<feDropShadow in="SourceGraphic" dx="0" dy="2.5" stdDeviation="2.2" flood-color="#000" flood-opacity=".65" result="bs"/>'
      + '<feMerge><feMergeNode in="bs"/><feMergeNode in="sp2"/></feMerge>'
      + '</filter>';
    s += '</defs>';
